const canonical=[{"quizType":"manufacturing-meaning","id":7,"index":6,"old":{"id":7,"sectionId":"all","question":"「NC」に一番近い意味はどれですか？","choices":["コンピューターで自動的に機械を動かす方法です（数値制御）","手で機械を動かすこと","機械の電気を切ること","品質を調べること"],"correctIndex":0,"explanation":"「NC」とは、コンピューターで自動的に機械を動かす方法です（数値制御）"},"new":{"id":7,"sectionId":"all","question":"「NC」に一番近い意味はどれですか？","choices":["数値情報によって工作機械などの動きを自動制御する方式です（数値制御）","手で機械を動かすこと","機械の電気を切ること","品質を調べること"],"correctIndex":0,"explanation":"正解は「数値情報によって工作機械などの動きを自動制御する方式」です。NCは数値制御を指し、コンピューターを用いるCNCはその一形態です。"}},{"quizType":"manufacturing-meaning","id":12,"index":11,"old":{"id":12,"sectionId":"all","question":"「エラー」に一番近い意味はどれですか？","choices":["間違いや機械の故障が起きた状態です","仕事がうまくいった状態","製品が完成した状態","機械が速く動く状態"],"correctIndex":0,"explanation":"「エラー」とは、間違いや機械の故障が起きた状態です"},"new":{"id":12,"sectionId":"all","question":"「エラー」に一番近い意味はどれですか？","choices":["入力・処理・動作などに誤りや異常が起きた状態です","仕事がうまくいった状態","製品が完成した状態","機械が速く動く状態"],"correctIndex":0,"explanation":"正解は「入力・処理・動作などに誤りや異常が起きた状態」です。故障は原因の一つになり得ますが、エラーそのものと同義ではありません。"}},{"quizType":"manufacturing-meaning","id":20,"index":19,"old":{"id":20,"sectionId":"all","question":"「コンベア」に一番近い意味はどれですか？","choices":["ものを自動で移動させる流れ送りの機械です","ものを高いところに上げる機械","ものをくるくる回す機械","ものを認識する機械"],"correctIndex":0,"explanation":"「コンベア」とは、ものを自動で移動させる流れ送りの機械です"},"new":{"id":20,"sectionId":"all","question":"「コンベア」に一番近い意味はどれですか？","choices":["ベルトやローラーなどで物を連続的に運ぶ搬送装置です","ものを高いところに上げる機械","ものをくるくる回す機械","ものを認識する機械"],"correctIndex":0,"explanation":"正解は「ベルトやローラーなどで物を連続的に運ぶ搬送装置」です。コンベアは工程間の物品搬送に使われます。"}},{"quizType":"manufacturing-meaning","id":21,"index":20,"old":{"id":21,"sectionId":"all","question":"「ショート」に一番近い意味はどれですか？","choices":["電気が間違ったルートに流れる事故です（短絡）","電気が切れること","電気が多くなること","機械が止まること"],"correctIndex":0,"explanation":"「ショート」とは、電気が間違ったルートに流れる事故です（短絡）"},"new":{"id":21,"sectionId":"all","question":"「ショート」に一番近い意味はどれですか？","choices":["電位の異なる導体どうしが低い抵抗でつながる状態です（短絡）","電気が切れること","電気が多くなること","機械が止まること"],"correctIndex":0,"explanation":"正解は「電位の異なる導体どうしが低い抵抗でつながる状態」です。短絡では大電流や発熱が生じる危険がありますが、用語自体は回路の状態を表します。"}},{"quizType":"manufacturing-meaning","id":25,"index":24,"old":{"id":25,"sectionId":"all","question":"「タクトタイム」に一番近い意味はどれですか？","choices":["1つの製品を作るのにかかる目安の時間です","1日の総作業時間","機械を動かす最大時間","休憩を取る時間"],"correctIndex":0,"explanation":"「タクトタイム」とは、1つの製品を作るのにかかる目安の時間です"},"new":{"id":25,"sectionId":"all","question":"「タクトタイム」に一番近い意味はどれですか？","choices":["顧客の必要数に合わせて、製品を1個ずつ作るべき時間間隔です","1日の総作業時間","機械を動かす最大時間","休憩を取る時間"],"correctIndex":0,"explanation":"正解は「顧客の必要数に合わせて、製品を1個ずつ作るべき時間間隔」です。実際に1個を作る所要時間はサイクルタイムであり、区別します。"}},{"quizType":"manufacturing-meaning","id":29,"index":28,"old":{"id":29,"sectionId":"all","question":"「ドライバー」に一番近い意味はどれですか？","choices":["ネジを回して締めたりゆるめたりする道具です","ボルトを締める道具","金属を切る道具","金属を打つ道具"],"correctIndex":0,"explanation":"「ドライバー」とは、ネジを回して締めたりゆるめたりする道具です"},"new":{"id":29,"sectionId":"all","question":"「ドライバー」に一番近い意味はどれですか？","choices":["ねじを回して締めたり緩めたりする手工具です","金属板を切断する専用のこぎりです","金属を切る道具","金属を打つ道具"],"correctIndex":0,"explanation":"正解は「ねじを回して締めたり緩めたりする手工具」です。切断用のこぎり、穴あけ工具、打撃工具とは用途が異なります。"}},{"quizType":"manufacturing-meaning","id":31,"index":30,"old":{"id":31,"sectionId":"all","question":"「ニコイチ」に一番近い意味はどれですか？","choices":["2つの壊れたものから1つの使えるものを作ることです","2人で1つの仕事をすること","2回に分けて検査すること","2つの製品を組み合わせること"],"correctIndex":0,"explanation":"「ニコイチ」とは、2つの壊れたものから1つの使えるものを作ることです"},"new":{"id":31,"sectionId":"all","question":"「ニコイチ」に一番近い意味はどれですか？","choices":["二つの物から使える部分を組み合わせ、一つを作るという俗な言い方です","2人で1つの仕事をすること","2回に分けて検査すること","2つの製品を組み合わせること"],"correctIndex":0,"explanation":"正解は「二つの物から使える部分を組み合わせ、一つを作るという俗な言い方」です。正式な作業標準では、部品流用や組合せの可否を手順・品質基準で確認します。"}},{"quizType":"manufacturing-meaning","id":35,"index":34,"old":{"id":35,"sectionId":"all","question":"「バリ」に一番近い意味はどれですか？","choices":["金属を加工したときにできるとがった余りの部分です","金属の表面の汚れ","金属の裏側の穴","金属の色の斑"],"correctIndex":0,"explanation":"「バリ」とは、金属を加工したときにできるとがった余りの部分です"},"new":{"id":35,"sectionId":"all","question":"「バリ」に一番近い意味はどれですか？","choices":["切削・成形などの加工後、縁などに生じる不要な突起です","金属の表面の汚れ","金属の裏側の穴","金属の色の斑"],"correctIndex":0,"explanation":"正解は「加工後、縁などに生じる不要な突起」です。金属に限らず、樹脂などの加工でも生じます。"}},{"quizType":"manufacturing-meaning","id":53,"index":52,"old":{"id":53,"sectionId":"all","question":"「レンチ」に一番近い意味はどれですか？","choices":["ボルトやナットを締める大きな道具です","ネジを回す道具","金属を切る道具","穴を開ける道具"],"correctIndex":0,"explanation":"「レンチ」とは、ボルトやナットを締める大きな道具です"},"new":{"id":53,"sectionId":"all","question":"「レンチ」に一番近い意味はどれですか？","choices":["ボルトやナットを締めたり緩めたりする手工具です","木材を切る手工具です","金属を切る道具","穴を開ける道具"],"correctIndex":0,"explanation":"正解は「ボルトやナットを締めたり緩めたりする手工具」です。工具の大きさは定義条件ではありません。"}},{"quizType":"manufacturing-meaning","id":54,"index":53,"old":{"id":54,"sectionId":"all","question":"「レーザー加工」に一番近い意味はどれですか？","choices":["レーザー光線を使って金属を切ったり穴を開けたりする加工方法です","熱で金属を溶かして加工すること","金属を押して加工すること","金属を磨いて加工すること"],"correctIndex":0,"explanation":"「レーザー加工」とは、レーザー光線を使って金属を切ったり穴を開けたりする加工方法です"},"new":{"id":54,"sectionId":"all","question":"「レーザー加工」に一番近い意味はどれですか？","choices":["レーザー光を利用して材料を切断したり穴を開けたりする加工方法です","手工具だけで材料を折り曲げる加工です","金属を押して加工すること","金属を磨いて加工すること"],"correctIndex":0,"explanation":"正解は「レーザー光を利用して材料を切断したり穴を開けたりする加工方法」です。レーザー加工には熱作用を利用する方式があるため、旧誤答の「熱で加工」は排除根拠になりません。"}},{"quizType":"manufacturing-meaning","id":55,"index":54,"old":{"id":55,"sectionId":"all","question":"「ロット」に一番近い意味はどれですか？","choices":["一度に作る製品のまとまった数です","製品の一つ一つの名前","製品の色の種類","製品の重さの単位"],"correctIndex":0,"explanation":"「ロット」とは、一度に作る製品のまとまった数です"},"new":{"id":55,"sectionId":"all","question":"「ロット」に一番近い意味はどれですか？","choices":["同じ条件で扱う製品や材料のまとまり（管理単位）です","製品の一つ一つの名前","製品の色の種類","製品の重さの単位"],"correctIndex":0,"explanation":"正解は「同じ条件で扱う製品や材料のまとまり」です。ロットは個数そのものではなく、製造・検査・追跡でまとめて扱う単位です。"}},{"quizType":"manufacturing-meaning","id":57,"index":56,"old":{"id":57,"sectionId":"all","question":"「不良品」に一番近い意味はどれですか？","choices":["基準に合わない品質の悪い製品です","基準を満たした製品","検査前の製品","完成した製品"],"correctIndex":0,"explanation":"「不良品」とは、基準に合わない品質の悪い製品です"},"new":{"id":57,"sectionId":"all","question":"「不良品」に一番近い意味はどれですか？","choices":["定められた品質基準に適合しない製品です","基準を満たした製品","検査前の製品","完成した製品"],"correctIndex":0,"explanation":"正解は「定められた品質基準に適合しない製品」です。見た目の良し悪しではなく、仕様や検査基準への適合で判定します。"}},{"quizType":"manufacturing-meaning","id":60,"index":59,"old":{"id":60,"sectionId":"all","question":"「亀裂」に一番近い意味はどれですか？","choices":["ものの表面に入った裂け目です","ものの表面の汚れ","ものが欠けた状態","ものが曲がった状態"],"correctIndex":0,"explanation":"「亀裂」とは、ものの表面に入った裂け目です"},"new":{"id":60,"sectionId":"all","question":"「亀裂」に一番近い意味はどれですか？","choices":["材料や部品に生じた細い割れ目（ひび）です","ものの表面の汚れ","ものが欠けた状態","ものが曲がった状態"],"correctIndex":0,"explanation":"正解は「材料や部品に生じた細い割れ目」です。亀裂は表面から確認できるものだけでなく、内部に生じる場合もあります。"}},{"quizType":"manufacturing-meaning","id":92,"index":91,"old":{"id":92,"sectionId":"all","question":"「六角レンチ」に一番近い意味はどれですか？","choices":["六角の穴のボルトを締めるL字形の道具です","丸い穴のボルトを締める道具","ネジを回す道具","金属を切る道具"],"correctIndex":0,"explanation":"「六角レンチ」とは、六角の穴のボルトを締めるL字形の道具です"},"new":{"id":92,"sectionId":"all","question":"「六角レンチ」に一番近い意味はどれですか？","choices":["六角穴付きボルトなどを締めたり緩めたりする工具です","丸い穴のボルトを締める道具","ネジを回す道具","金属を切る道具"],"correctIndex":0,"explanation":"正解は「六角穴付きボルトなどを締めたり緩めたりする工具」です。L字形のほか、T形やソケット形もあります。"}},{"quizType":"manufacturing-meaning","id":104,"index":103,"old":{"id":104,"sectionId":"all","question":"「劣化」に一番近い意味はどれですか？","choices":["機械や部品が時間とともに古くなって品質が下がることです","機械や部品が新しくなること","機械や部品が壊れること","機械や部品が汚れること"],"correctIndex":0,"explanation":"「劣化」とは、機械や部品が時間とともに古くなって品質が下がることです"},"new":{"id":104,"sectionId":"all","question":"「劣化」に一番近い意味はどれですか？","choices":["時間や使用、環境の影響で性能や品質が低下することです","機械や部品が新しくなること","機械や部品が壊れること","機械や部品が汚れること"],"correctIndex":0,"explanation":"正解は「時間や使用、環境の影響で性能や品質が低下すること」です。単に古いだけでなく、機能や性質の低下を指します。"}},{"quizType":"manufacturing-meaning","id":128,"index":127,"old":{"id":128,"sectionId":"all","question":"「報告」に一番近い意味はどれですか？","choices":["上司やチームに情報を伝えることです","上司に質問すること","上司に相談すること","上司に手伝いを求めること"],"correctIndex":0,"explanation":"「報告」とは、上司やチームに情報を伝えることです"},"new":{"id":128,"sectionId":"all","question":"「報告」に一番近い意味はどれですか？","choices":["仕事の経過や結果などの情報を、必要な相手に伝えることです","上司に質問すること","上司に相談すること","上司に手伝いを求めること"],"correctIndex":0,"explanation":"正解は「仕事の経過や結果などを必要な相手に伝えること」です。報告先は職場の指示系統や手順によって決まります。"}},{"quizType":"manufacturing-meaning","id":129,"index":128,"old":{"id":129,"sectionId":"all","question":"「報連相」に一番近い意味はどれですか？","choices":["報告・連絡・相談の 3つをまとめた言葉です","保管・冷却・作業の 3つ","本番・練習・参加の 3つ","保全・連携・創造の 3つ"],"correctIndex":0,"explanation":"「報連相」とは、報告・連絡・相談の 3つをまとめた言葉です"},"new":{"id":129,"sectionId":"all","question":"「報連相」に一番近い意味はどれですか？","choices":["報告・連絡・相談の3つをまとめた言葉です","保管・冷却・作業の 3つ","本番・練習・参加の 3つ","保全・連携・創造の 3つ"],"correctIndex":0,"explanation":"正解は「報告・連絡・相談の3つをまとめた言葉」です。それぞれ、結果を伝える、情報を共有する、意見を求める役割があります。"}},{"quizType":"manufacturing-meaning","id":144,"index":143,"old":{"id":144,"sectionId":"all","question":"「定期点検」に一番近い意味はどれですか？","choices":["決められた時間に機械や設備を点検することです","壊れたときだけ点検すること","毎日点検すること","注文があったとき点検すること"],"correctIndex":0,"explanation":"「定期点検」とは、決められた時間に機械や設備を点検することです"},"new":{"id":144,"sectionId":"all","question":"「定期点検」に一番近い意味はどれですか？","choices":["決められた周期や計画に従って機械や設備を点検することです","壊れたときだけ点検すること","製品を出荷した後だけ点検すること","注文があったとき点検すること"],"correctIndex":0,"explanation":"正解は「決められた周期や計画に従って点検すること」です。日常点検も周期的ですが、この選択肢群では計画保全としての定期点検を問います。"}},{"quizType":"manufacturing-meaning","id":153,"index":152,"old":{"id":153,"sectionId":"all","question":"「巻き込まれ」に一番近い意味はどれですか？","choices":["動いている機械やベルトに体が入ってしまう事故です","機械にぶつかる事故","高いところから落ちる事故","電気にかかる事故"],"correctIndex":0,"explanation":"「巻き込まれ」とは、動いている機械やベルトに体が入ってしまう事故です"},"new":{"id":153,"sectionId":"all","question":"「巻き込まれ」に一番近い意味はどれですか？","choices":["身体や衣服などが動いている機械・回転部に巻き込まれる事故です","機械にぶつかる事故","高いところから落ちる事故","電気にかかる事故"],"correctIndex":0,"explanation":"正解は「身体や衣服などが動いている機械・回転部に巻き込まれる事故」です。停止・隔離など定められた安全手順を守る必要があります。"}},{"quizType":"manufacturing-meaning","id":154,"index":153,"old":{"id":154,"sectionId":"all","question":"「引火」に一番近い意味はどれですか？","choices":["簡単に燃えるものに火が移って燃えることです","電気が体に流れること","機械が過熱すること","ガスが漏れること"],"correctIndex":0,"explanation":"「引火」とは、簡単に燃えるものに火が移って燃えることです"},"new":{"id":154,"sectionId":"all","question":"「引火」に一番近い意味はどれですか？","choices":["可燃性の物質に火源が触れ、燃え始めることです","電気が体に流れること","機械が過熱すること","ガスが漏れること"],"correctIndex":0,"explanation":"正解は「可燃性の物質に火源が触れ、燃え始めること」です。引火性物質は火気・静電気など事業場で定めた着火源管理が必要です。"}},{"quizType":"manufacturing-meaning","id":157,"index":156,"old":{"id":157,"sectionId":"all","question":"「成形」に一番近い意味はどれですか？","choices":["材料を型に入れて形を作ることです","材料を削って形を作ること","材料を切って形を作ること","材料を磨いて形を作ること"],"correctIndex":0,"explanation":"「成形」とは、材料を型に入れて形を作ることです"},"new":{"id":157,"sectionId":"all","question":"「成形」に一番近い意味はどれですか？","choices":["材料に力や熱などを加え、目的の形に作る加工です","製品が基準どおりか検査することです","材料を倉庫へ運ぶことです","完成品を箱に保管することです"],"correctIndex":0,"explanation":"正解は「材料に力や熱などを加え、目的の形に作る加工」です。型を使う方法は成形の代表例ですが、用語をそれだけに限定しません。"}},{"quizType":"manufacturing-meaning","id":160,"index":159,"old":{"id":160,"sectionId":"all","question":"「抜き取り検査」に一番近い意味はどれですか？","choices":["一部の製品を無作為に選んで検査することです","すべての製品を検査すること","全部の製品を一つずつ検査すること","製品を二度検査すること"],"correctIndex":0,"explanation":"「抜き取り検査」とは、一部の製品を無作為に選んで検査することです"},"new":{"id":160,"sectionId":"all","question":"「抜き取り検査」に一番近い意味はどれですか？","choices":["ロットから一部の製品を抜き取り、その結果でロットを判定する検査です","すべての製品を検査すること","全部の製品を一つずつ検査すること","製品を二度検査すること"],"correctIndex":0,"explanation":"正解は「ロットから一部を抜き取り、その結果でロットを判定する検査」です。抽出方法や個数は定められた検査計画に従います。"}},{"quizType":"manufacturing-meaning","id":172,"index":171,"old":{"id":172,"sectionId":"all","question":"「故障」に一番近い意味はどれですか？","choices":["機械が壊れて動かなくなることです","機械が速く動くこと","機械が自動で動くこと","機械の電気が入ること"],"correctIndex":0,"explanation":"「故障」とは、機械が壊れて動かなくなることです"},"new":{"id":172,"sectionId":"all","question":"「故障」に一番近い意味はどれですか？","choices":["機械が本来求められる機能を果たせなくなることです","機械が速く動くこと","機械が自動で動くこと","機械の電気が入ること"],"correctIndex":0,"explanation":"正解は「機械が本来求められる機能を果たせなくなること」です。完全停止だけでなく、性能低下や誤動作も故障になり得ます。"}},{"quizType":"manufacturing-meaning","id":183,"index":182,"old":{"id":183,"sectionId":"all","question":"「校正」に一番近い意味はどれですか？","choices":["測る道具の正確さを正しく調整することです","測る道具を交換すること","測る道具を点検すること","測る道具を掃除すること"],"correctIndex":0,"explanation":"「校正」とは、測る道具の正確さを正しく調整することです"},"new":{"id":183,"sectionId":"all","question":"「校正」に一番近い意味はどれですか？","choices":["測定器の指示値と標準が示す値との関係を確認することです","測る道具を交換すること","測る道具を点検すること","測る道具を掃除すること"],"correctIndex":0,"explanation":"正解は「測定器の指示値と標準が示す値との関係を確認すること」です。校正は関係を確立する操作であり、値を合わせる調整そのものとは別です。"}},{"quizType":"manufacturing-meaning","id":196,"index":195,"old":{"id":196,"sectionId":"all","question":"「歩留まり」に一番近い意味はどれですか？","choices":["使った材料に対してよい製品ができた割合です","生産した製品の合計","検査に合格した数","注文を受けた数"],"correctIndex":0,"explanation":"「歩留まり」とは、使った材料に対してよい製品ができた割合です"},"new":{"id":196,"sectionId":"all","question":"「歩留まり」に一番近い意味はどれですか？","choices":["投入した材料や数量に対して、良品として得られた量の割合です","生産した製品の合計","検査に合格した数","注文を受けた数"],"correctIndex":0,"explanation":"正解は「投入した量に対して良品として得られた量の割合」です。何を投入量・良品量とするかは工程の管理基準で明確にします。"}},{"quizType":"manufacturing-meaning","id":203,"index":202,"old":{"id":203,"sectionId":"all","question":"「治具」に一番近い意味はどれですか？","choices":["作業をやりやすくするために作られた専用の道具です","製品を検査する機械","機械を動かす装置","ものを測る道具"],"correctIndex":0,"explanation":"「治具」とは、作業をやりやすくするために作られた専用の道具です"},"new":{"id":203,"sectionId":"all","question":"「治具」に一番近い意味はどれですか？","choices":["加工や組立で、対象物を正しい位置に決めて保持する補助具です","製品を検査する機械","機械を動かす装置","ものを測る道具"],"correctIndex":0,"explanation":"正解は「対象物を正しい位置に決めて保持する補助具」です。測定器や機械本体とは役割が異なります。"}},{"quizType":"manufacturing-meaning","id":211,"index":210,"old":{"id":211,"sectionId":"all","question":"「溶接」に一番近い意味はどれですか？","choices":["金属を熱で溶かしてくっつける作業です","金属を押して形にする作業","金属を切る作業","金属を磨く作業"],"correctIndex":0,"explanation":"「溶接」とは、金属を熱で溶かしてくっつける作業です"},"new":{"id":211,"sectionId":"all","question":"「溶接」に一番近い意味はどれですか？","choices":["熱や圧力などを利用して、材料どうしを接合する方法です","金属を押して形にする作業","金属を切る作業","金属を磨く作業"],"correctIndex":0,"explanation":"正解は「熱や圧力などを利用して材料どうしを接合する方法」です。材料を溶融させる方法だけでなく、圧力を利用する方法もあります。"}},{"quizType":"manufacturing-meaning","id":234,"index":233,"old":{"id":234,"sectionId":"all","question":"「研磨」に一番近い意味はどれですか？","choices":["表面を磨いてなめらかにしたり光沢を出したりすることです","表面を削ること","表面を塗ること","表面を切ること"],"correctIndex":0,"explanation":"「研磨」とは、表面を磨いてなめらかにしたり光沢を出したりすることです"},"new":{"id":234,"sectionId":"all","question":"「研磨」に一番近い意味はどれですか？","choices":["表面を磨いて、なめらかさや光沢を得る加工です","材料を大きく二つに切断する加工です","表面を塗ること","表面を切ること"],"correctIndex":0,"explanation":"正解は「表面を磨いて、なめらかさや光沢を得る加工」です。研磨でも微小な材料除去を伴うため、旧誤答の「表面を削る」は排除できません。"}},{"quizType":"manufacturing-meaning","id":238,"index":237,"old":{"id":238,"sectionId":"all","question":"「稼働率」に一番近い意味はどれですか？","choices":["機械が実際に動いている時間の割合です","機械が壊れている時間の割合","機械を点検する時間の割合","機械を掃除する時間の割合"],"correctIndex":0,"explanation":"「稼働率」とは、機械が実際に動いている時間の割合です"},"new":{"id":238,"sectionId":"all","question":"「稼働率」に一番近い意味はどれですか？","choices":["利用できる時間に対して、機械が実際に稼働した時間の割合です","機械が壊れている時間の割合","機械を点検する時間の割合","機械を掃除する時間の割合"],"correctIndex":0,"explanation":"正解は「利用できる時間に対する実稼働時間の割合」です。管理目的により時間区分が異なるため、計算時は分母の定義を確認します。"}},{"quizType":"manufacturing-meaning","id":250,"index":249,"old":{"id":250,"sectionId":"all","question":"「良品」に一番近い意味はどれですか？","choices":["検査に合格した品質のよい製品です","検査に不合格の製品","検査前の製品","途中の製品"],"correctIndex":0,"explanation":"「良品」とは、検査に合格した品質のよい製品です"},"new":{"id":250,"sectionId":"all","question":"「良品」に一番近い意味はどれですか？","choices":["定められた品質基準に適合し、検査に合格した製品です","検査に不合格の製品","検査前の製品","途中の製品"],"correctIndex":0,"explanation":"正解は「定められた品質基準に適合し、検査に合格した製品」です。主観的な良し悪しではなく、仕様・検査基準で判定します。"}},{"quizType":"manufacturing-meaning","id":255,"index":254,"old":{"id":255,"sectionId":"all","question":"「設備保全」に一番近い意味はどれですか？","choices":["機械や設備が壊れないように守って管理することです","壊れた機械を修理すること","新しい機械を買うこと","機械を速く動かすこと"],"correctIndex":0,"explanation":"「設備保全」とは、機械や設備が壊れないように守って管理することです"},"new":{"id":255,"sectionId":"all","question":"「設備保全」に一番近い意味はどれですか？","choices":["設備の機能を維持・回復するため、点検・整備・修理などを行う活動です","生産数量だけを集計する活動です","新しい機械を買うこと","機械を速く動かすこと"],"correctIndex":0,"explanation":"正解は「設備の機能を維持・回復するための点検・整備・修理などの活動」です。修理は設備保全に含まれるため、旧選択肢では複数成立していました。"}},{"quizType":"manufacturing-meaning","id":264,"index":263,"old":{"id":264,"sectionId":"all","question":"「転倒」に一番近い意味はどれですか？","choices":["人が倒れる事故です","高いところから落ちる事故","機械にぶつかる事故","ものに挟まれる事故"],"correctIndex":0,"explanation":"「転倒」とは、人が倒れる事故です"},"new":{"id":264,"sectionId":"all","question":"「転倒」に一番近い意味はどれですか？","choices":["人がほぼ同じ高さの床面などで、滑ったりつまずいたりして倒れる事故です","高いところから落ちる事故","機械にぶつかる事故","ものに挟まれる事故"],"correctIndex":0,"explanation":"正解は「ほぼ同じ高さの床面などで滑ったりつまずいたりして倒れる事故」です。高い場所から落ちる墜落・転落とは区別します。"}},{"quizType":"manufacturing-meaning","id":265,"index":264,"old":{"id":265,"sectionId":"all","question":"「転落」に一番近い意味はどれですか？","choices":["人がころびながら落ちる事故です","人がその場で倒れる事故","人が機械にぶつかる事故","人が挟まれる事故"],"correctIndex":0,"explanation":"「転落」とは、人がころびながら落ちる事故です"},"new":{"id":265,"sectionId":"all","question":"「転落」に一番近い意味はどれですか？","choices":["階段や段差、高所などから下へ落ちる事故です","人がその場で倒れる事故","人が機械にぶつかる事故","人が挟まれる事故"],"correctIndex":0,"explanation":"正解は「階段や段差、高所などから下へ落ちる事故」です。同一平面上で倒れる転倒とは区別します。"}},{"quizType":"manufacturing-meaning","id":277,"index":276,"old":{"id":277,"sectionId":"all","question":"「錆」に一番近い意味はどれですか？","choices":["金属が湿気と反応してできる赤色や黒色の腐食です","金属の磨かれた表面","金属の曲がった状態","金属のすり減った状態"],"correctIndex":0,"explanation":"「錆」とは、金属が湿気と反応してできる赤色や黒色の腐食です"},"new":{"id":277,"sectionId":"all","question":"「錆」に一番近い意味はどれですか？","choices":["金属が酸素や水分などと反応して生じる腐食生成物です","金属の磨かれた表面","金属の曲がった状態","金属のすり減った状態"],"correctIndex":0,"explanation":"正解は「金属が酸素や水分などと反応して生じる腐食生成物」です。色や生成条件は金属・環境によって異なります。"}},{"quizType":"manufacturing-meaning","id":279,"index":278,"old":{"id":279,"sectionId":"all","question":"「防塵マスク」に一番近い意味はどれですか？","choices":["細かいちりやほこりを吸い込まないためのマスクです","顔を守るためのマスク","においを防ぐためのマスク","ガスを防ぐためのマスク"],"correctIndex":0,"explanation":"「防塵マスク」とは、細かいちりやほこりを吸い込まないためのマスクです"},"new":{"id":279,"sectionId":"all","question":"「防塵マスク」に一番近い意味はどれですか？","choices":["粉じんの吸入を減らすために、作業に合ったものを正しく着用する呼吸用保護具です","顔を守るためのマスク","においを防ぐためのマスク","ガスを防ぐためのマスク"],"correctIndex":0,"explanation":"正解は「粉じんの吸入を減らす呼吸用保護具」です。作業に適した区分を選び、顔への密着を確認して正しく着用します。ガス用の防毒マスクとは用途が異なります。"}},{"quizType":"manufacturing-meaning","id":281,"index":280,"old":{"id":281,"sectionId":"all","question":"「電動工具」に一番近い意味はどれですか？","choices":["電気で動く道具のまとめた呼び方です","手で動かす道具のまとめた呼び方","エアーで動く道具のまとめた呼び方","水で動く道具のまとめた呼び方"],"correctIndex":0,"explanation":"「電動工具」とは、電気で動く道具のまとめた呼び方です"},"new":{"id":281,"sectionId":"all","question":"「電動工具」に一番近い意味はどれですか？","choices":["電気で動く道具をまとめていう呼び方です","手で動かす道具のまとめた呼び方","エアーで動く道具のまとめた呼び方","水で動く道具のまとめた呼び方"],"correctIndex":0,"explanation":"正解は「電気で動く道具をまとめていう呼び方」です。手動工具や空気圧工具とは動力源が異なります。"}},{"quizType":"manufacturing-meaning","id":283,"index":282,"old":{"id":283,"sectionId":"all","question":"「養生」に一番近い意味はどれですか？","choices":["作業中に近くの場所や部品を汚れやキズから守ることです","作業中に体を守ること","機械を守ること","製品を検査すること"],"correctIndex":0,"explanation":"「養生」とは、作業中に近くの場所や部品を汚れやキズから守ることです"},"new":{"id":283,"sectionId":"all","question":"製造現場で、作業前に行う「養生」に一番近い意味はどれですか？","choices":["周囲や部品を覆い、汚れや傷から保護することです","作業中に体を守ること","機械を守ること","製品を検査すること"],"correctIndex":0,"explanation":"正解は「周囲や部品を覆い、汚れや傷から保護すること」です。この問題は製造現場で作業前に行う保護の意味を問います。材料を硬化・安定させる別の用法とは区別します。"}}]
