const phase60Hash='28f17991a2d08b587c05e4515f93c81e2d73ee8164732a8001e94cc8862ff78c'
const get=(f)=>quizzes[f.quizType].questions[f.index]
const scored=(q)=>({id:q.id,sectionId:q.sectionId,question:q.question,choices:q.choices,correctIndex:q.correctIndex,explanation:q.explanation})
const sha=(v)=>createHash('sha256').update(JSON.stringify(v)).digest('hex')

test('Phase 62 applies 37 canonical and 74 static-derived complete objects',()=>{
  assert.equal(canonical.length,37);assert.equal(derived.length,74);assert.equal(new Set([...canonical,...derived].map(f=>`${f.quizType}:${f.id}:${f.index}`)).size,111)
  for(const f of [...canonical,...derived]){const q=get(f);assert.deepEqual(scored(q),f.new,`${f.quizType}:${f.id}`);assert.equal(f.old.correctIndex,f.new.correctIndex);assert.equal(f.old.choices.length,f.new.choices.length);assert.equal(q.choices[q.correctIndex],f.new.choices[f.new.correctIndex]);assert.equal(new Set(q.choices).size,q.choices.length)}
  for(const f of canonical){for(const type of ['manufacturing-word','manufacturing-conversation-50']){const x=derived.find(d=>d.id===f.id&&d.quizType===type);assert.ok(x);const q=get(x);const term=quizzes['manufacturing-meaning'].questions[f.index].question.match(/「([^」]+)」/)?.[1]??(f.id===283?'養生':'');assert.equal(q.choices[q.correctIndex],term);assert.ok(q.explanation.includes(term))}}
})

test('Phase 62 protects holds, Phase 60, shared Japanese data and global integrity',()=>{
  assert.deepEqual(quizzes['manufacturing-meaning'].questions.find(q=>q.id===202),protectedObjects.id202)
  assert.deepEqual([8,20,23,25,27].map(id=>quizzes['skill-test-machining'].questions.find(q=>q.id===id)),protectedObjects.h5)
  assert.deepEqual([95,100].map(id=>quizzes['japanese-n4'].questions.find(q=>q.id===id)),protectedObjects.n4)
  assert.equal(sha(MANUFACTURING_MIGRATION_TARGETS.map(t=>quizzes[t.quizType].questions.find(q=>q.id===t.id))),phase60Hash)
  const all=Object.values(quizzes).flatMap(q=>q.questions);assert.equal(all.length,1513)
  for(const quiz of Object.values(quizzes)){assert.equal(new Set(quiz.questions.map(q=>q.id)).size,quiz.questions.length);for(const q of quiz.questions){assert.ok(q.question.trim());assert.ok(q.explanation.trim());assert.ok(q.choices.length>0);assert.equal(new Set(q.choices).size,q.choices.length);assert.ok(Number.isInteger(q.correctIndex)&&q.correctIndex>=0&&q.correctIndex<q.choices.length)}}
})

test('Phase 62 v2 migrates exactly 111 legacy objects and preserves user metadata',()=>{
  assert.equal(MANUFACTURING_MIGRATION_V2_TARGET_COUNT,111);assert.equal(new Set(MANUFACTURING_MIGRATION_V2_TARGETS.map(t=>`${t.quizType}:${t.id}`)).size,111)
  for(const f of [...canonical,...derived]){const legacy={...f.old,selectedIndexes:[3],isCorrect:false,score:4,progress:2,timestamp:'2026-08-08T00:00:00Z'};const got=migrateManufacturingStoredValueV2([legacy],f.quizType)[0];assert.deepEqual(scored(got),f.new);assert.deepEqual(got.selectedIndexes,[3]);assert.equal(got.isCorrect,false);assert.equal(got.score,4);assert.equal(got.progress,2);assert.equal(got.timestamp,'2026-08-08T00:00:00Z')}
  const f=canonical[0],legacy={...f.old,answerIndex:2};assert.deepEqual(migrateManufacturingStoredValueV2([{...legacy,question:legacy.question+' '}],f.quizType),[{...legacy,question:legacy.question+' '}]);assert.deepEqual(migrateManufacturingStoredValueV2([{id:f.id}],f.quizType),[{id:f.id}]);assert.deepEqual(migrateManufacturingStoredValueV2([legacy],'japanese-n4'),[legacy]);assert.deepEqual(migrateManufacturingStoredValueV2([protectedObjects.id202],'manufacturing-meaning'),[protectedObjects.id202])
})

test('Phase 62 storage v1 then v2 supports all paths, exceptions and idempotence',()=>{
  const f=canonical[0];for(const prefix of ['wrong','normal-session','exam-session']){const key=`${prefix}-${f.quizType}`,data=new Map([[key,JSON.stringify([{...f.old,answeredAt:9}])]]),storage={getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v)};migrateManufacturingQuestionStorage(storage);assert.equal(JSON.parse(data.get(key))[0].question,f.new.question);assert.equal(JSON.parse(data.get(key))[0].answeredAt,9);assert.equal(data.get('manufacturing-question-migration-v1'),'1');assert.equal(data.get('manufacturing-question-migration-v2'),'1');const once=JSON.stringify([...data]);migrateManufacturingQuestionStorage(storage);assert.equal(JSON.stringify([...data]),once)}
  const v1Legacy={id:84,sectionId:'all',question:'「保護具」に一番近い意味はどれですか？',choices:['作業中に体を守る道具のまとめた呼び方です','機械を守るカバー','製品を守る箱','道具をしまう箱'],correctIndex:0,explanation:'「保護具」とは、作業中に体を守る道具のまとめた呼び方です'};const data=new Map([['wrong-manufacturing-meaning',JSON.stringify([v1Legacy,canonical[0].old])]]),storage={getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v)};migrateManufacturingQuestionStorage(storage);const got=JSON.parse(data.get('wrong-manufacturing-meaning'));assert.equal(got[0].choices[0],'作業中に体を守る道具をまとめた呼び方です');assert.equal(got[1].question,canonical[0].new.question)
  assert.doesNotThrow(()=>migrateManufacturingQuestionStorage());assert.doesNotThrow(()=>migrateManufacturingQuestionStorage({getItem:()=>{throw Error('blocked')},setItem:()=>{throw Error('blocked')}}));const broken=new Map([['wrong-manufacturing-meaning','{']]);assert.doesNotThrow(()=>migrateManufacturingQuestionStorage({getItem:k=>broken.get(k)??null,setItem:(k,v)=>broken.set(k,v)}));assert.doesNotThrow(()=>migrateManufacturingQuestionStorage({getItem:k=>k.includes('migration')?null:JSON.stringify([canonical[0].old]),setItem:()=>{throw Error('full')}}))
})

test('Phase 62 signatures detect middle content and formal game scope stays 207',()=>{
  for(const type of ['manufacturing-meaning','manufacturing-word','manufacturing-conversation-50']){const base=quizzes[type].questions,s=buildManufacturingQuizContentSignature(type,base),i=Math.floor(base.length/2),mut=(patch)=>base.map((q,n)=>n===i?{...q,...patch(q)}:q);assert.notEqual(buildManufacturingQuizContentSignature(type,mut(q=>({question:q.question+'!'}))),s);assert.notEqual(buildManufacturingQuizContentSignature(type,mut(q=>({choices:[...q.choices].reverse()}))),s);assert.notEqual(buildManufacturingQuizContentSignature(type,mut(q=>({correctIndex:(q.correctIndex+1)%q.choices.length}))),s)}
  assert.deepEqual(GAME_QUIZ_TYPES,['japanese-n4','japanese-n3','japanese-n2']);const counts=Object.fromEntries(GAME_QUIZ_TYPES.map(t=>[t,buildGameQuestionsFromQuizzes(t).length]));assert.deepEqual(counts,{'japanese-n4':33,'japanese-n3':89,'japanese-n2':85});assert.equal(Object.values(counts).reduce((a,b)=>a+b,0),207);for(const type of ['manufacturing-meaning','manufacturing-word','manufacturing-conversation','manufacturing-conversation-50','skill-test-machining'])assert.throws(()=>buildGameQuestionsFromQuizzes(type),/Unsupported game quiz type/)
})
